import sys
n, m, k, sx, sy = map(int, sys.stdin.read().split())
MOD = 10**9 + 7
cur = {(sx, sy): 1}
ans = 0
for _ in range(k):
    nxt = {}
    for (x, y), c in cur.items():
        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m:
                nxt[(nx, ny)] = (nxt.get((nx, ny), 0) + c) % MOD
            else:
                ans = (ans + c) % MOD
    cur = nxt
print(ans)

